// DCL - PHAI co volatile
class Singleton {
    private static volatile Singleton instance;

    static Singleton get() {
        if (instance == null) {                 // check 1: khong lock, nhanh
            synchronized (Singleton.class) {
                if (instance == null) {         // check 2: da co lock
                    instance = new Singleton(); // cap phat -> ctor -> gan
                }
            }
        }
        return instance;
    }
}

