// AtomicInteger.incrementAndGet ve ban chat la vong lap CAS
int incrementAndGet(AtomicInteger a) {
    while (true) {
        int cur = a.get();
        int next = cur + 1;
        if (a.compareAndSet(cur, next)) return next;  // thua thi lap lai
    }
}

