// ReentrantLock: co timeout, huy duoc, nhieu Condition
private final ReentrantLock lock = new ReentrantLock();

boolean transferOrGiveUp(int amount) throws InterruptedException {
    if (!lock.tryLock(200, TimeUnit.MILLISECONDS)) {
        return false;                 // khong treo vo han
    }
    try {
        balance += amount;
        return true;
    } finally {
        lock.unlock();                // BAT BUOC trong finally
    }
}

// Producer/consumer bang wait/notify - chu y while va notifyAll
synchronized void put(T item) throws InterruptedException {
    while (queue.size() == CAPACITY) {   // WHILE, khong phai IF
        wait();                          // nha monitor trong luc cho
    }
    queue.add(item);
    notifyAll();                         // danh thuc ca producer lan consumer
}

// Cach hien dai: hai Condition rieng, signal an toan
private final ReentrantLock lock = new ReentrantLock();
private final Condition notFull  = lock.newCondition();
private final Condition notEmpty = lock.newCondition();

void put2(T item) throws InterruptedException {
    lock.lock();
    try {
        while (queue.size() == CAPACITY) notFull.await();
        queue.add(item);
        notEmpty.signal();
    } finally {
        lock.unlock();
    }
}

