// Sua: thu tu khoa nhat quan theo identityHashCode, CO tie lock cho truong hop trung hash
private static final Object TIE_LOCK = new Object();

void transferSafe(Account a, Account b, int amt) {
    int ha = System.identityHashCode(a), hb = System.identityHashCode(b);
    if (ha == hb) {                  // hiem nhung co that: khong con thu tu de sap
        synchronized (TIE_LOCK) {    // thieu doan nay la deadlock quay lai nguyen ven
            synchronized (a) { synchronized (b) { a.debit(amt); b.credit(amt); } }
        }
        return;
    }
    Account first  = ha < hb ? a : b;
    Account second = (first == a) ? b : a;
    synchronized (first) {
        synchronized (second) { a.debit(amt); b.credit(amt); }
    }
}

